if ON_DATABRICKS:
    # Re-run safety: Unity Catalog won't replace a table that a declared foreign key points to, so remove
    # this notebook's own key declarations first (foreign keys, then primary keys).
    for stmt in reversed(KEY_CONSTRAINTS):
        table, name = re.match(r"ALTER TABLE (\w+) ADD CONSTRAINT (\w+)", stmt).groups()
        if spark.catalog.tableExists(table):
            spark.sql(f"ALTER TABLE {table} DROP CONSTRAINT IF EXISTS {name}" +
                      (" CASCADE" if name.startswith("pk_") else ""))

def local_compat(stmt):
    """Identity and generated columns need the Databricks runtime; open-source Delta can't create them
    through SQL. The local test therefore uses plain columns. The seed supplies every id explicitly, and
    the queries compute stakes from their parts, so every result is the same either way."""
    stmt = stmt.replace(" GENERATED BY DEFAULT AS IDENTITY", "")
    return re.sub(r" GENERATED ALWAYS AS \((.*?)\)(?=,\n|\n\))", "", stmt)


for stmt in DDL:
    spark.sql(stmt if ON_DATABRICKS else local_compat(stmt))
print(f"{len(DDL)} tables created")

