# MAGIC %md ## 2. Enforced constraints (CHECK), and informational keys (PK/FK, Unity Catalog only)

# COMMAND ----------

CHECKS = [
    ('players', 'ck_players_registration_channel', "registration_channel IN ('web','app','retail')"),
    ('players', 'ck_players_kyc_status', "kyc_status IN ('not_started','pending','verified','rejected')"),
    ('players', 'ck_players_status', "status IN ('active','blocked','self_excluded','closed')"),
    ('player_vip_tier_history', 'ck_viphist_period', 'valid_to_utc IS NULL OR valid_to_utc > valid_from_utc'),
    ('player_status_history', 'ck_player_status_history_status', "status IN ('active','blocked','self_excluded','closed')"),
    ('player_status_history', 'ck_player_status_history_kyc_status', "kyc_status IN ('not_started','pending','verified','rejected')"),
    ('player_status_history', 'ck_statushist_period', 'valid_to_utc IS NULL OR valid_to_utc > valid_from_utc'),
    ('player_tag_history', 'ck_taghist_period', 'valid_to_utc IS NULL OR valid_to_utc > valid_from_utc'),
    ('wallets', 'ck_wallet_nonneg', 'real_balance >= 0 AND bonus_balance >= 0'),
    ('wallet_transactions', 'ck_wallet_transactions_txn_type', "txn_type IN ('deposit','withdrawal','bet_stake','bet_win','bonus_credit', 'bonus_debit','refund','reversal','manual_adjustment')"),
    ('wallet_transactions', 'ck_wallet_transactions_balance_type', "balance_type IN ('real','bonus')"),
    ('wallet_transactions', 'ck_wallet_transactions_direction', "direction IN ('credit','debit')"),
    ('wallet_transactions', 'ck_wtxn_amount_pos', 'amount > 0'),
    ('wallet_transactions', 'ck_wtxn_balance_math', "balance_after = balance_before + CASE WHEN direction = 'credit' THEN amount ELSE -amount END"),
    ('wallet_transactions', 'ck_wtxn_reversal_link', "(txn_type = 'reversal' AND reversal_of_wallet_txn_id IS NOT NULL) OR (txn_type <> 'reversal' AND reversal_of_wallet_txn_id IS NULL)"),
    ('wallet_transactions', 'ck_wtxn_one_source', 'CASE WHEN related_deposit_attempt_id IS NULL THEN 0 ELSE 1 END + CASE WHEN related_withdrawal_id IS NULL THEN 0 ELSE 1 END + CASE WHEN related_bet_id IS NULL THEN 0 ELSE 1 END + CASE WHEN related_player_bonus_id IS NULL THEN 0 ELSE 1 END + CASE WHEN reversal_of_wallet_txn_id IS NULL THEN 0 ELSE 1 END <= 1'),
    ('wallet_transactions', 'ck_wtxn_reason', "txn_type NOT IN ('manual_adjustment','reversal') OR reason IS NOT NULL"),
    ('deposit_attempts', 'ck_deposit_attempts_status', "status IN ('initiated','success','failed')"),
    ('deposit_attempts', 'ck_deposit_amount_pos', 'amount > 0'),
    ('withdrawal_requests', 'ck_withdrawal_requests_status', "status IN ('requested','approved','paid','failed','cancelled')"),
    ('withdrawal_requests', 'ck_withdrawal_amount_pos', 'amount > 0'),
    ('bets', 'ck_bets_product', "product IN ('sportsbook','casino','retail')"),
    ('bets', 'ck_bets_channel', "channel IN ('web','app','retail')"),
    ('bets', 'ck_bets_status', "status IN ('open','won','lost','void','cashed_out')"),
    ('bets', 'ck_bets_stake_nonneg', 'stake_real_amount >= 0 AND stake_bonus_amount >= 0'),
    ('bets', 'ck_bets_stake_positive', 'stake_real_amount + stake_bonus_amount > 0'),
    ('bets', 'ck_bets_bonus_funding', '(stake_bonus_amount = 0 AND player_bonus_id IS NULL) OR (stake_bonus_amount > 0 AND player_bonus_id IS NOT NULL)'),
    ('bets', 'ck_bets_payout_nonneg', 'payout_amount >= 0'),
    ('bets', 'ck_bets_settled_time', "status = 'open' OR settled_at_utc IS NOT NULL"),
    ('sports_bet_details', 'ck_sports_bet_details_bet_class', "bet_class IN ('single','accumulator')"),
    ('sports_bet_details', 'ck_sportsdet_legs', "(bet_class = 'single' AND leg_count = 1) OR (bet_class = 'accumulator' AND leg_count >= 2)"),
    ('bet_legs', 'ck_bet_legs_leg_result', "leg_result IN ('pending','won','lost','void')"),
    ('bet_legs', 'ck_leg_odds', 'odds > 1'),
    ('bonus_campaigns', 'ck_bonus_campaigns_campaign_type', "campaign_type IN ('registration','deposit_match','cashback','free_spins','other')"),
    ('bonus_campaigns', 'ck_campaign_rollover', 'rollover_multiple >= 0'),
    ('player_bonuses', 'ck_player_bonuses_status', "status IN ('active','completed','expired','forfeited')"),
    ('player_bonuses', 'ck_pbonus_amount_pos', 'granted_amount > 0'),
    ('player_bonuses', 'ck_pbonus_resolved', "(status = 'active' AND resolved_at_utc IS NULL) OR (status <> 'active' AND resolved_at_utc IS NOT NULL)"),
    ('player_bonuses', 'ck_pbonus_expiry', 'expires_at_utc > granted_at_utc'),
]     # (table, constraint name, expression): ENUM values and the MySQL CHECKs
for table, name, expr in CHECKS:
    spark.sql(f"ALTER TABLE {table} ADD CONSTRAINT {name} CHECK ({expr})")
print(f"{len(CHECKS)} CHECK constraints added (enforced on every write)")

if ON_DATABRICKS:
    for stmt in KEY_CONSTRAINTS:
        spark.sql(stmt)
    print(f"{len(KEY_CONSTRAINTS)} primary and foreign keys declared in Unity Catalog (informational)")
else:
    print(f"local run: {len(KEY_CONSTRAINTS)} PK/FK declarations skipped (Unity Catalog only)")

